import assert from 'node:assert/strict';
import { test } from 'node:test';
import { multiply } from '../multiply.js';

test('R1.1 multiply', () => assert.equal(multiply(4, 3), 12));

export const divide = (a, b) => {
  if (b === 0) throw new RangeError('division by zero');
  return a / b;
};

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { divide } from '../divide.js';

test('R2.1 divide', () => assert.equal(divide(12, 3), 4));
test('R2.2 divide by zero throws', () => assert.throws(() => divide(1, 0), { name: 'RangeError', message: 'division by zero' }));
